import { typography } from "../lib/typography.shared";
import { memo, type ComponentProps, type ReactNode } from "react";
import { ArrowUpRight } from "lucide-react";
import { cn } from "cn";
import { GitHubDark } from "@ridemountainpig/svgl-react";
import { Badge } from "../components/badge";
import { sampleFooterGroups } from "../lib/navigation.shared";
import { Card } from "../components/card";

interface FooterProps extends ComponentProps<"footer"> {
  brand?: string;
  homeHref?: string;
  description?: string;
  groups?: {
    title: string;
    links: {
      label: string;
      href: string;
    }[];
  }[];
  githubHref?: string;
  copyright?: string;
  callout?: {
    title: string;
    description: string;
    label: string;
    href: string;
  };
  action?: ReactNode;
}

export const FooterStacked = memo(function FooterStacked({ brand = "Hangry UI", homeHref = "#home", description = "Thoughtful components. Less setup. More time to build.", groups = sampleFooterGroups, githubHref = "#github", copyright = `© ${new Date().getFullYear()} Hangry UI`, callout, action, className, children, ...props }: FooterProps = {}) {
  return (<footer {...props} data-slot="footer" data-layout="stacked" className={cn("w-full border border-border bg-background text-foreground", className)}>
    {callout && <div className="border-b border-border p-6 sm:p-8">
      <Card title={callout.title} description={callout.description} className="max-w-none!" footer={action ?? <a href={callout.href} className="inline-flex min-h-10 items-center gap-2 text-sm font-medium hover:underline focus-visible:outline-2 focus-visible:outline-ring">{callout.label}<ArrowUpRight size={16} aria-hidden="true" /></a>} />
    </div>}
    <div className={cn("gap-10 p-6 sm:p-8", "flex flex-col items-center text-center")}>
      <div>
        <a href={homeHref} className="text-xl font-semibold focus-visible:outline-2 focus-visible:outline-ring">{brand}</a>
        {<p className={`mt-3 max-w-sm ${typography.body}`}>{description}</p>}
        {<div className="mt-4"><Badge variant="success">Open source</Badge></div>}
        {children}
      </div>
      <div className="grid grid-cols-2 gap-8">
        {groups.map(group => <nav key={group.title} aria-label={group.title}>
          {<h3 className={`mb-4 ${typography.subsectionTitle}`}>{group.title}</h3>}
          <ul className="space-y-3">
            {group.links.map(link => <li key={link.href}><a href={link.href} className="text-sm text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring">{link.label}</a></li>)}
          </ul>
        </nav>)}
      </div>
    </div>
    <div className="flex flex-wrap items-center justify-between gap-4 border-t border-border px-6 py-4 text-xs text-muted-foreground sm:px-8">
      <span>{copyright}</span>
      {githubHref && <a href={githubHref} className="inline-flex min-h-9 items-center gap-2 hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"><GitHubDark width={16} height={16} aria-hidden="true" />GitHub</a>}
    </div>
  </footer>);
});

"use client";

import { memo, type ReactNode } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion, type HTMLMotionProps } from "motion/react";
import { CircleCheck, CircleDashed, CircleX, Clock3, SearchCheck, Send, TriangleAlert } from "lucide-react";
import { typography } from "../lib/typography.shared";

interface BadgeProps extends Omit<HTMLMotionProps<"span">, "children"> {
  children?: ReactNode;
  variant?: "pending" | "in-progress" | "submitted" | "in-review" | "success" | "failed" | "expired" | "neutral" | "info" | "warning" | "error" | "blue" | "purple" | "pink" | "teal" | "orange";
}

const statuses = {
  pending: { label: "Pending", icon: TriangleAlert },
  "in-progress": { label: "In progress", icon: CircleDashed },
  submitted: { label: "Submitted", icon: Send },
  "in-review": { label: "In review", icon: SearchCheck },
  success: { label: "Success", icon: CircleCheck },
  failed: { label: "Failed", icon: CircleX },
  expired: { label: "Expired", icon: Clock3 },
};

const styles = {
  pending: "bg-orange-500/10 text-orange-500",
  "in-progress": "bg-sky-500/10 text-sky-500",
  submitted: "bg-violet-500/10 text-violet-500",
  "in-review": "bg-yellow-500/10 text-yellow-600 dark:text-yellow-400",
  success: "bg-green-500/10 text-green-600 dark:text-green-400",
  failed: "bg-red-500/10 text-red-500",
  expired: "bg-neutral-500/10 text-neutral-500",
  neutral: "bg-neutral-500/10 text-neutral-500",
  info: "bg-sky-500/10 text-sky-500",
  warning: "bg-amber-500/10 text-amber-600 dark:text-amber-400",
  error: "bg-red-500/10 text-red-500",
  blue: "bg-blue-500/10 text-blue-500",
  purple: "bg-purple-500/10 text-purple-500",
  pink: "bg-pink-500/10 text-pink-500",
  teal: "bg-teal-500/10 text-teal-600 dark:text-teal-400",
  orange: "bg-orange-500/10 text-orange-500",
};

export const Badge = memo(function Badge({ children, variant = "success", className = "", ...props }: BadgeProps = {}) {
  const status = variant in statuses ? statuses[variant as keyof typeof statuses] : undefined;
  const Icon = status?.icon;
  const reducedMotion = useReducedMotion();

  return (
    <motion.span
      initial={reducedMotion ? false : { opacity: 0, y: 20 }}
      whileInView={reducedMotion ? undefined : { opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.5 }}
      whileHover={reducedMotion ? undefined : { y: -2, scale: 1.03 }}
      transition={{ duration: reducedMotion ? 0 : 0.35, ease: "easeOut" }}
      className={`inline-flex items-center gap-2 rounded-none border-0 px-3 py-2 ${typography.label} ${styles[variant]} ${className}`}
      {...props}
    >
      {Icon && <Icon aria-hidden="true" className="size-[1.15em] shrink-0" strokeWidth={2.25} />}
      {children ?? status?.label ?? "New release"}
    </motion.span>
  );
});

import { typography } from "../lib/typography.shared";
import type { ComponentProps, ReactNode } from "react";

interface CardProps extends Omit<ComponentProps<"article">, "title"> {
  title?: string;
  description?: string;
  footer?: ReactNode;
}

export function Card({ title = "Room for your next idea", description = "A simple starting point for something great. Make it yours.", children, footer, className = "", ...props }: CardProps = {}) {
  return <article className={`w-full max-w-sm border border-border bg-card p-6 text-base leading-7 text-card-foreground shadow-sm ${className}`} {...props}>
    {title && <h3 className={typography.sectionTitle}>{title}</h3>}
    {description && <p className={`mt-2 ${typography.body}`}>{description}</p>}
    {children && <div className={title || description || footer ? "mt-5" : "h-full min-h-0"}>{children}</div>}
    {footer && <footer className="mt-5 border-t border-border pt-4">{footer}</footer>}
  </article>;
}

/** Shared text hierarchy for documentation and component content. */
export const typography = {
  pageTitle: "text-4xl font-semibold tracking-tight text-foreground sm:text-5xl",
  sectionTitle: "text-2xl font-semibold tracking-tight text-foreground",
  subsectionTitle: "text-xl font-semibold tracking-tight text-foreground",
  body: "text-base leading-7 text-muted-foreground",
  label: "text-sm font-medium",
  caption: "text-sm leading-6 text-muted-foreground",
} as const;
